+/** A condition accepted by conditional option helpers. */
+export type OptionCondition = string | OptionDependencyCondition | OptionDependency;
+
+function asDependency(condition: OptionCondition, required: boolean): OptionDependency {
+  if (typeof condition === "string") return { option: condition, required };
+  if ("anyOf" in condition || "allOf" in condition || "required" in condition) {
+    return { ...condition, required: condition.required ?? required };
+  }
