+}
+
+/** Creates an option that requires its condition to be satisfied. */
+export function requiredWhen<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  return conditionalOption({ ...asDependency(condition, true), required: true }, flagSpec, valueParser);
+}
+
+/** Creates an option that is visible only when its condition is satisfied. */
+export function optionalWhen<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  return conditionalOption(asDependency(condition, false), flagSpec, valueParser);
+}
+
+/** Creates an option with conditional dependency metadata. */
+export function conditionalOption<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  const names = conditionalNames(flagSpec);
+  const dependsOn = asDependency(condition, false);
+  return valueParser === undefined
