+/** A condition accepted by conditional option helpers. */
+export type OptionCondition = string | OptionDependencyCondition | OptionDependency;
+
+function asDependency(condition: OptionCondition, required: boolean): OptionDependency {
+  if (typeof condition === "string") return { option: condition, required };
+  if ("anyOf" in condition || "allOf" in condition || "required" in condition) {
+    return { ...condition, required: condition.required ?? required };
+  }
+  return { ...condition, required };
+}
+
+function conditionalNames(flagSpec: OptionName | readonly OptionName[]): readonly OptionName[] {
+  return typeof flagSpec === "string" ? [flagSpec] : flagSpec;
+}
+
+/** Creates an option that requires its condition to be satisfied. */
+export function requiredWhen<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  return conditionalOption({ ...asDependency(condition, true), required: true }, flagSpec, valueParser);
+}
+
+/** Creates an option that is visible only when its condition is satisfied. */
+export function optionalWhen<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
